import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])

    grid = [[False] * m for _ in range(n)]

    ret = False

    while True:
        found = False
        for i in range(n):
            if found:
                break
            for j in range(m):
                if not grid[i][j]:
                    for k in range(n):
                        grid[k][j] = True
                    for k in range(m):
                        grid[i][k] = True
                    found = True
                    break

        if not found:
            break

        ret = not ret

    if not ret:
        print("Malvika")
    else:
        print("Akshat")

if __name__ == "__main__":
    main()

